// Proposed new file: src/utils/sessionEpoch.ts
import type { AxiosRequestConfig } from "axios";

declare module "axios" {
  interface AxiosRequestConfig<D = any, P = any> {
    sessionEpoch?: number;
  }
}

let sessionEpoch = 0;
export const currentSessionEpoch = () => sessionEpoch;
export const invalidateSession = () => ++sessionEpoch;
export const isFreshLogin = (url = "") =>
  /\/auth\/v[23]\/sso\/login(?:[?#]|$)/.test(url);
export const isStaleSession = (config?: AxiosRequestConfig) =>
  config?.sessionEpoch !== undefined &&
  config.sessionEpoch !== currentSessionEpoch();

