// src/hooks/service/index.ts: add epoch to the existing record.
let refreshTokenRequest:
  | {
      sessionEpoch: number;
      accessToken: string | undefined;
      controller: AbortController;
      promise: Promise<void>;
    }
  | undefined;

export const getPendingRefreshToken = (): Promise<void> | undefined => {
  const request = refreshTokenRequest;
  return request &&
    request.sessionEpoch === currentSessionEpoch() &&
    !request.controller.signal.aborted
    ? request.promise
    : undefined;
};

snippets.acquisition-changes:
export const getRefreshToken = (): Promise<void> => {
  const { store } = getHooksBase();
  // Keep the current expiry parsing and three-hour reuse rule.
  // Replace its bare return with: return Promise.resolve();

  const pending = getPendingRefreshToken();
  if (pending && refreshTokenRequest?.accessToken === store.token) {
    return pending;
  }

  signal.getRefreshToken?.abort();
  const controller = new AbortController();
  const sessionEpoch = currentSessionEpoch();
  signal.getRefreshToken = controller;
  const promise = service.post(
    getEndPoint("/auth/v2/sso/refreshtoken"),
    { singleUIAuthorization: store.token },
    { signal: controller.signal }
  ).then(() => undefined).finally(() => {
    if (refreshTokenRequest?.controller === controller) {
      refreshTokenRequest = undefined;
    }
    if (signal.getRefreshToken === controller) {
      signal.getRefreshToken = undefined;
    }
  });
  refreshTokenRequest = {
    sessionEpoch, accessToken: store.token, controller, promise,
  };
  return promise;
};

